import{_ as i,o as a,c as r,a3 as e}from"./chunks/framework.jVlskimI.js";const c=JSON.parse('{"title":"历史更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"UPDATE_old.md","filePath":"UPDATE_old.md"}'),t={name:"UPDATE_old.md"};function o(n,l,p,s,h,d){return a(),r("div",{"data-pagefind-body":!0},l[0]||(l[0]=[e('<h1 id="历史更新日志" tabindex="-1">历史更新日志 <a class="header-anchor" href="#历史更新日志" aria-label="Permalink to &quot;历史更新日志&quot;">​</a></h1><h1 id="_11-28" tabindex="-1">11.28 <a class="header-anchor" href="#_11-28" aria-label="Permalink to &quot;11.28&quot;">​</a></h1><ul><li>兼容更多版本</li><li>完善了温度系统的机制</li><li>侧边栏新增温度信息 弃去传统的 BOSS 血条显示信息避免大幅遮挡</li><li>新增高亮显示</li><li>新增新手装备</li><li>移除自动整理背包</li><li>修复菜单部分 UI 问题</li><li>新增更好的聊天</li><li>新增头顶显示信息</li><li>新增仿 JE 快速回血以及饱食度显示</li><li>修复 UI 导致玩家角色重复显示问题</li><li>新增卫星地图</li><li>新增称号昵称</li><li>新增精英怪物 - 精英僵尸</li><li>游戏主体版本更新至 1.21.120</li><li>修复官网问题反馈无法正常反馈问题</li><li>修复侧边栏温度值显示过长问题</li><li>修复食物无法正常回温问题</li><li>修复精英怪物刷新概率过高问题</li><li>尝试修复领地导致崩服问题</li><li>尝试修复连锁无法正常连锁 BUG</li><li>新增领地飞行/ikfly</li><li>尝试加强区块漏斗刷物修护</li></ul><h1 id="_11-13" tabindex="-1">11.13 <a class="header-anchor" href="#_11-13" aria-label="Permalink to &quot;11.13&quot;">​</a></h1><ul><li>对接 QBOT</li><li>新增搬运功能 /eh</li><li>优化性能逻辑</li><li>新增温度系统</li><li>修改教程书配方为纸+泥土</li><li>官网新增问题反馈与 BUG 反馈收集</li><li>更新了一些小提示</li><li>新增发射器挖掘方块机制</li><li>优化反矿透逻辑</li><li>新增连锁系统 /fm</li><li>新增指令 /ping 查看延迟</li><li>修复菜单-个人设置部分按钮异常</li><li>关闭村民交易平衡</li><li>修复物品无法正常堆叠问题</li><li>修复背包物品交互回弹问题</li><li>新增排行榜展示栏 (x=0 z=200 y=0)</li></ul><h1 id="_11-12" tabindex="-1">11.12 <a class="header-anchor" href="#_11-12" aria-label="Permalink to &quot;11.12&quot;">​</a></h1><ul><li>优化死亡掉落箱逻辑</li><li>优化自动清理性能 关闭了定时间隔清理</li><li>优化侧边栏在手机端显示重叠</li><li>优化侧边栏刷新间隔 避免不必要的卡顿</li><li>新增金币获取方式：“赏金猎人” <br>通过击杀对应的生物获取对应的金币奖励</li><li>修复 back 命令返回错误</li><li>修复死亡后可以反复刷经验 BUG</li></ul><h2 id="_8-5-8-更新内容" tabindex="-1">8.5.8 更新内容 <a class="header-anchor" href="#_8-5-8-更新内容" aria-label="Permalink to &quot;8.5.8 更新内容&quot;">​</a></h2><h3 id="空岛服更新" tabindex="-1">空岛服更新 <a class="header-anchor" href="#空岛服更新" aria-label="Permalink to &quot;空岛服更新&quot;">​</a></h3><h2 id="空岛-3-0-更新内容" tabindex="-1">空岛 3.0 更新内容 <a class="header-anchor" href="#空岛-3-0-更新内容" aria-label="Permalink to &quot;空岛 3.0 更新内容&quot;">​</a></h2><ul><li><p>优化刷石机矿物概率</p></li><li><p>任务系列彻底重做</p></li><li><p>新增修改群系功能</p></li><li><p>下界空岛正式开放</p></li><li><p>正式加入精灵球</p></li><li><p>新增菜单 UI</p></li><li><p>优化任务奖励堆叠有概率消失问题</p></li><li><p>修复地狱无法正常生成地狱门问题</p></li><li><p>暂时去除树叶快速腐烂</p></li><li><p>修复岛屿挑战-新手-好的习惯无法正常完成</p></li><li><p>优化岛屿等级逻辑异常</p></li><li><p>优化岛屿挑战-新手-新的起点等级异常</p></li><li><p>新增复活无敌时间 10s</p></li><li><p>新增范围拾取 <code>/mt</code></p></li><li><p>因暂时去除树叶快速腐烂 新增连锁 <code>/fm</code></p></li><li><p>修复岛屿任务-新手一切的开始奖励描述有误</p></li><li><p>修复岛屿挑战-基础-起飞的岛屿! 异常</p></li><li><p>新增苹果皮</p></li><li><p>修改生物刷新机制</p></li><li><p>新手、基础任务重做</p></li><li><p>重置了所有基础任务进度</p></li><li><p>新增玩家个人商店</p></li><li><p>修改岩浆回收次数为 <strong>5</strong></p></li><li><p>优化性能 大幅度减少崩服情况</p></li><li><p>任务奖励重做</p></li><li><p>新增 <strong>精灵球机制</strong></p></li><li><p>新增 <strong>村庄显示</strong></p></li><li><p>新增 <strong>自动切换工具功能</strong></p></li><li><p>新增 <strong>自动补货功能</strong></p></li><li><p>修改发射器破坏方块条件为：<strong>仅限铁镐触发</strong></p></li></ul><h4 id="新增电梯功能" tabindex="-1">新增电梯功能： <a class="header-anchor" href="#新增电梯功能" aria-label="Permalink to &quot;新增电梯功能：&quot;">​</a></h4><ul><li>煤炭块：<strong>最大垂直跨度 5 格 方块之间不可存在方块</strong></li><li>铜块：<strong>最大垂直跨度 5 格 方块之间可以存在方块</strong></li></ul><hr><ul><li>青金石块：<strong>最大垂直跨度 8 格 方块之间不可存在方块</strong></li><li>红石块：<strong>最大垂直跨度 8 格 方块之间可以存在方块</strong></li></ul><hr><ul><li>铁块：<strong>最大垂直跨度 10 格 方块之间不可存在方块</strong></li><li>金块：<strong>最大垂直跨度 10 格 方块之间可以存在方块</strong></li></ul><hr><ul><li>下届合金块：<strong>最大垂直跨度 30 格 方块之间可以存在方块</strong></li></ul><h2 id="_8-5-7-更新内容" tabindex="-1">8.5.7 更新内容 <a class="header-anchor" href="#_8-5-7-更新内容" aria-label="Permalink to &quot;8.5.7 更新内容&quot;">​</a></h2><h3 id="生存服更新" tabindex="-1">生存服更新： <a class="header-anchor" href="#生存服更新" aria-label="Permalink to &quot;生存服更新：&quot;">​</a></h3><ul><li>重构传送系统</li><li>修复定位栏发黑的问题</li><li>尝试修复配方问题</li><li>暂且移除 PVP 功能开关</li><li>重构经济页面</li><li>商店更新</li><li>更新菜单</li><li>个人设置菜单更新</li><li>新增给钟功能 /gc</li></ul><h3 id="资源服更新" tabindex="-1">资源服更新： <a class="header-anchor" href="#资源服更新" aria-label="Permalink to &quot;资源服更新：&quot;">​</a></h3><ul><li>优化服务器 addon 导致的卡顿</li><li>新增禁用方块插件</li><li>禁止放置红石类以及其他的方块</li><li>新增复活无敌 10s 时间</li></ul><h2 id="_8-5-6-更新内容" tabindex="-1">8.5.6 更新内容 <a class="header-anchor" href="#_8-5-6-更新内容" aria-label="Permalink to &quot;8.5.6 更新内容&quot;">​</a></h2><ul><li>修复<a href="http://map.inspurs.work:22222/" target="_blank" rel="noreferrer">卫星地图</a>无法正常访问</li><li>新增 LK-Stats 统计信息</li><li>适配最新版 <a href="/plugins/pland.html">Pland</a></li><li>优化家具卡服问题</li><li>去除部分 addon</li><li>优化服务器性能</li><li>优化客户端性能</li><li>更新商店系统 具体内容自行研究</li><li>整体更新传送系统</li><li>再次修复 65 刷物品 BUG</li><li>新增经验球自动合并机制</li><li>自动补充暂时去除自动补上潜影盒内的物品</li><li>新增耕地防止踩踏</li><li>关闭了村民交易平衡</li><li>新增游戏功能</li><li>已就绪 WS 同步功能 请敬请期待资源服正式上线</li><li>奥里给更新 现在动物每隔五分钟就会拉一坨便便</li><li>更新菜单内容</li><li>新增小提示 帮助新手更好的了解服务器指令</li><li>恢复家园数据</li><li>新增解除下界高度限制</li><li>新增单挑系统</li><li>修复农夫乐事无法正常加载</li><li>修复材质包无法正常加载</li><li>恢复幻翼刷新机制</li><li>修复游戏内信息不转发</li><li>更新黑名单系统</li><li>新增正则插件</li><li>机器人新增指令：服务器状态、tps、在线人数、余额等等</li><li>修复 TPS 无法正常显示问题</li><li>修复<a href="/plugins/fc.html">灵魂出窍</a>异常</li><li>移除游戏中心</li><li>适配<a href="/plugins/alg.html">奥利给工艺</a></li><li>优化猪人塔等红石机器对性能的影响</li><li>修复金币排行榜无法正常显示</li></ul><h2 id="_8-5-5-更新内容" tabindex="-1">8.5.5 更新内容 <a class="header-anchor" href="#_8-5-5-更新内容" aria-label="Permalink to &quot;8.5.5 更新内容&quot;">​</a></h2><ul><li>去除成就系统</li><li>重做 wiki 网站（感谢小李的协助）</li><li>卫星地图地址改为: <a href="http://map.inspurs.work:22222/" target="_blank" rel="noreferrer">http://map.inspurs.work:22222/</a></li><li>卫星地图网页新增网页聊天（需要在游戏内设置好密码之后在网页上登上账号具体请看 <a href="/plugins/bdslm.html">Wiki</a>）</li><li>修复 Addon 导致的报错刷屏等影响的开服速度</li><li>连锁新增方块 下界疣块</li><li>优化连锁树木时诺树木附近有对应的树叶则会跟着被连锁挖掘掉</li><li>优化灵魂出窍开关提示 已同步至英文</li><li>修改远古残骸连锁价格为 5 金币/块</li><li>新增连锁方块 黑曜石 连锁价格 5 金币/块</li><li>修复在线转账无法显示在线玩家列表</li><li>装备强化正式投放至生存服 详细请看 Wiki</li><li>优化了邀请码机制 防止有人利用小号重复获取金币</li><li>修复连锁时运算时间期间服务器出现假死</li><li>优化连锁运算逻辑与计算时间</li><li>新增玩法 奥里给工艺</li><li>优化 QBOT 性能 减少对服务器不必要的性能开销</li><li>去除信息统计插件 将性能极致优化最大化</li><li>优化侧边栏性能</li><li>去除了一些 QBOT 插件 优化 QBOT 响应速度</li><li>强化装备已兼容奥里给装备</li><li>假人新增破坏，攻击，交互功能，更改功能描述</li><li>新增功能 TrustedSkin 信任每个皮肤</li><li>新增功能 ThrowableFireball 可投掷的烈焰弹</li><li>优化 为发射器破坏方块做好了领地兼容</li><li>新增生电功能插件(村显、史显、tick 测试等) 具体请看 Wiki</li><li>领地更新 具体请看 Wiki</li><li>IP 更换为 mc.inspurs.work</li><li>新增材质包共存：允许客户端资源包与服务端资源包叠加使用</li><li>适配树叶快速腐烂</li><li>TPA 更改为付费 30 金币/次 冷却时间为 60s</li><li>更改假人不再计入需要睡觉人数之内</li><li>二维圈地价格更改至 square * 5(平面内一格方块 5 元)</li><li>修复自动备份失效</li><li>修复奥里给斧头无法正常连锁</li><li>由于 PAPI 失效 暂时去除侧边栏</li><li>玩家睡眠百分比下调至 5%</li><li>修复连锁方块数量异常</li><li>修复连锁耐久消耗异常</li><li>修复连锁多余配置项(云杉木)</li><li>资源服整体架构更新( 856 中旬 上线 敬请期待)</li></ul>',28)]))}const g=i(t,[["render",o]]);export{c as __pageData,g as default};
